//! R validation of predictions with standard errors, partial residuals,
//! Breusch-Pagan / White tests and AFT survival curves (issue #80).
//!
//! References: `predict.lm`, `predict.glm`, `MASS::glm.nb`, `lmtest::bptest`,
//! `residuals(type = "partial")`, car's added-variable formula (`lsfit`),
//! `survival::psurvreg` and `predict(survreg, type = "quantile")`.
//! Generated by `tests/r_scripts/generate_predict_se_validation.R`.

#[path = "fixtures/predict_se_validation.rs"]
mod reference;

use anofox_regression::diagnostics::{
    added_variable, breusch_pagan, partial_residuals, partial_residuals_glm, white_test,
};
use anofox_regression::inference::{PredictSeError, PredictSeOptions, PredictWithSe, PredictionSe};
use anofox_regression::solvers::aft::{fit_aft, AftDistribution, AftOptions, AftRegressor};
use anofox_regression::solvers::penalized_glm::{
    fit_binomial, fit_gamma, fit_negbinomial, fit_poisson, BinomialOptions, GammaOptions,
    NegBinomialOptions, PenalizedGlmFamily, PenalizedGlmRegressor, PoissonOptions,
};
use anofox_regression::solvers::{
    BinomialRegressor, FittedRegressor, GammaRegressor, NegativeBinomialRegressor, OlsRegressor,
    PoissonRegressor, Regressor, RidgeRegressor, WlsRegressor,
};
use faer::{Col, Mat};
use reference::*;

const ETOL: f64 = 1e-12;

fn design() -> Mat<f64> {
    Mat::from_fn(60, 2, |i, j| if j == 0 { X1[i] } else { X2[i] })
}
fn x_cols() -> Vec<Vec<f64>> {
    vec![X1.to_vec(), X2.to_vec()]
}
fn new_design() -> Mat<f64> {
    Mat::from_fn(5, 2, |i, j| if j == 0 { NEW_X1[i] } else { NEW_X2[i] })
}
fn new_cols() -> Vec<Vec<f64>> {
    vec![NEW_X1.to_vec(), NEW_X2.to_vec()]
}
fn col(v: &[f64]) -> Col<f64> {
    Col::from_fn(v.len(), |i| v[i])
}

/// Asserts relative closeness and returns the max abs difference.
fn cmp(label: &str, got: &Col<f64>, want: &[f64], tol: f64) -> f64 {
    assert_eq!(got.nrows(), want.len(), "{label}: length");
    let mut max = 0.0f64;
    for (i, &w) in want.iter().enumerate() {
        let g = got[i];
        let d = (g - w).abs();
        assert!(
            d <= tol * w.abs().max(1.0),
            "{label}[{i}]: got {g:.12e}, R {w:.12e}"
        );
        max = max.max(d);
    }
    println!("{label}: max abs diff {max:.3e}");
    max
}

fn check_glm(label: &str, link: &PredictionSe, resp: &PredictionSe, r: [&[f64]; 6], tol: f64) {
    let [eta, se_eta, mu, se_mu, lwr, upr] = r;
    cmp(&format!("{label} eta"), &link.fit, eta, tol);
    cmp(&format!("{label} se_eta"), &link.se_fit, se_eta, tol);
    cmp(&format!("{label} mu"), &resp.fit, mu, tol);
    cmp(&format!("{label} se_mu"), &resp.se_fit, se_mu, tol);
    cmp(&format!("{label} mu_lwr"), &resp.lower, lwr, tol);
    cmp(&format!("{label} mu_upr"), &resp.upper, upr, tol);
    assert!(link.df.is_infinite() && link.residual_scale.is_none());
}

// ------------------------------------------------------------ linear models

fn check_linear<F: PredictWithSe>(label: &str, f: &F, r: [&[f64]; 7]) {
    let [fit, se, clwr, cupr, plwr, pupr, sigma] = r;
    let x = new_design();
    let c = f.predict_se(&x, &PredictSeOptions::new()).unwrap();
    cmp(&format!("{label} fit"), &c.fit, fit, 1e-9);
    cmp(&format!("{label} se_fit"), &c.se_fit, se, 1e-9);
    cmp(&format!("{label} conf lwr"), &c.lower, clwr, 1e-9);
    cmp(&format!("{label} conf upr"), &c.upper, cupr, 1e-9);
    assert!((c.residual_scale.unwrap() - sigma[0]).abs() < 1e-9);
    let p = f
        .predict_se(&x, &PredictSeOptions::new().prediction().level(0.9))
        .unwrap();
    // The prediction interval keeps se_fit as the SE of the mean (R se.fit).
    cmp(&format!("{label} pred se_fit"), &p.se_fit, se, 1e-9);
    cmp(&format!("{label} pred90 lwr"), &p.lower, plwr, 1e-9);
    cmp(&format!("{label} pred90 upr"), &p.upper, pupr, 1e-9);
    // Link and response scales coincide for a linear model.
    let l = f.predict_se(&x, &PredictSeOptions::new().link()).unwrap();
    cmp(&format!("{label} link"), &l.fit, fit, 1e-9);
}

#[test]
fn ols_matches_predict_lm() {
    let f = OlsRegressor::builder()
        .with_intercept(true)
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    check_linear(
        "OLS",
        &f,
        [
            &OLS_FIT,
            &OLS_SE,
            &OLS_CONF_LWR,
            &OLS_CONF_UPR,
            &OLS_PRED90_LWR,
            &OLS_PRED90_UPR,
            &OLS_SIGMA,
        ],
    );
}

#[test]
fn wls_matches_predict_lm() {
    let f = WlsRegressor::builder()
        .with_intercept(true)
        .weights(col(&W))
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    check_linear(
        "WLS",
        &f,
        [
            &WLS_FIT,
            &WLS_SE,
            &WLS_CONF_LWR,
            &WLS_CONF_UPR,
            &WLS_PRED90_LWR,
            &WLS_PRED90_UPR,
            &WLS_SIGMA,
        ],
    );
}

#[test]
fn ridge_matches_its_interval_api() {
    // R has no predict method for ridge; check consistency with the model's own
    // predict_with_interval (validated in issue40_ridge_prediction_interval.rs).
    use anofox_regression::core::IntervalType;
    let f = RidgeRegressor::builder()
        .with_intercept(true)
        .lambda(0.5)
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    let x = new_design();
    for (it, opts) in [
        (IntervalType::Confidence, PredictSeOptions::new()),
        (
            IntervalType::Prediction,
            PredictSeOptions::new().prediction(),
        ),
    ] {
        let a = f.predict_se(&x, &opts).unwrap();
        let b = f.predict_with_interval(&x, Some(it), 0.95);
        for i in 0..5 {
            assert!((a.lower[i] - b.lower[i]).abs() < 1e-10);
            assert!((a.upper[i] - b.upper[i]).abs() < 1e-10);
        }
    }
}

#[test]
fn linear_rejects_bad_input() {
    let f = OlsRegressor::builder()
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    let bad = Mat::<f64>::zeros(2, 3);
    assert!(matches!(
        f.predict_se(&bad, &PredictSeOptions::new()),
        Err(PredictSeError::DimensionMismatch {
            expected: 2,
            got: 3
        })
    ));
    assert!(matches!(
        f.predict_se(&new_design(), &PredictSeOptions::new().level(0.0)),
        Err(PredictSeError::InvalidLevel(_))
    ));
}

// ------------------------------------------------------------ penalized GLM engine

fn link_resp(
    f: impl Fn(&PredictSeOptions) -> Result<PredictionSe, PredictSeError>,
) -> (PredictionSe, PredictionSe) {
    (
        f(&PredictSeOptions::new().link()).unwrap(),
        f(&PredictSeOptions::new()).unwrap(),
    )
}

#[test]
fn engine_poisson_with_offset_matches_predict_glm() {
    let mut x = x_cols();
    x.push(OFFSET.to_vec());
    let opts = PoissonOptions {
        offset_column: Some(3),
        compute_inference: true,
        tolerance: ETOL,
        max_iterations: 200,
        ..Default::default()
    };
    let fit = fit_poisson(&Y_POIS, &x, &opts).unwrap();
    let mut nx = new_cols();
    nx.push(NEW_OFFSET.to_vec());
    let (l, r) = link_resp(|o| fit.predict_se(&nx, o));
    let refs = [
        &POIS_ETA[..],
        &POIS_SE_ETA,
        &POIS_MU,
        &POIS_SE_MU,
        &POIS_MU_LWR,
        &POIS_MU_UPR,
    ];
    check_glm("engine Poisson+offset", &l, &r, refs, 1e-8);

    // The builder with the offset held outside x.
    let b = PenalizedGlmRegressor::builder()
        .family(PenalizedGlmFamily::poisson())
        .compute_inference(true)
        .tolerance(ETOL)
        .max_iterations(200)
        .offset(col(&OFFSET))
        .build()
        .fit(&design(), &col(&Y_POIS))
        .unwrap();
    let off = col(&NEW_OFFSET);
    let (l, r) = link_resp(|o| b.predict_se_with_offset(&new_design(), &off, o));
    check_glm("builder Poisson+offset", &l, &r, refs, 1e-8);

    // A prediction interval is not defined for a GLM.
    assert_eq!(
        fit.predict_se(&nx, &PredictSeOptions::new().prediction())
            .unwrap_err(),
        PredictSeError::PredictionIntervalUnsupported
    );
    // Without inference there is no covariance.
    let no_inf = fit_poisson(
        &Y_POIS,
        &x,
        &PoissonOptions {
            compute_inference: false,
            ..opts
        },
    )
    .unwrap();
    assert!(matches!(
        no_inf.predict_se(&nx, &PredictSeOptions::new()),
        Err(PredictSeError::MissingCovariance(_))
    ));
}

#[test]
fn engine_binomial_matches_predict_glm() {
    let opts = BinomialOptions {
        compute_inference: true,
        tolerance: ETOL,
        max_iterations: 200,
        ..Default::default()
    };
    let fit = fit_binomial(&Y_BIN, &x_cols(), &opts).unwrap();
    let (l, r) = link_resp(|o| fit.predict_se(&new_cols(), o));
    check_glm(
        "engine binomial",
        &l,
        &r,
        [
            &BIN_ETA,
            &BIN_SE_ETA,
            &BIN_MU,
            &BIN_SE_MU,
            &BIN_MU_LWR,
            &BIN_MU_UPR,
        ],
        1e-8,
    );
}

#[test]
fn engine_gamma_matches_predict_glm() {
    let opts = GammaOptions {
        compute_inference: true,
        tolerance: ETOL,
        max_iterations: 200,
        ..Default::default()
    };
    let fit = fit_gamma(&Y_GAMMA, &x_cols(), &opts).unwrap();
    let (l, r) = link_resp(|o| fit.predict_se(&new_cols(), o));
    check_glm(
        "engine Gamma",
        &l,
        &r,
        [
            &GAMMA_ETA,
            &GAMMA_SE_ETA,
            &GAMMA_MU,
            &GAMMA_SE_MU,
            &GAMMA_MU_LWR,
            &GAMMA_MU_UPR,
        ],
        // The IRLS stopping rule leaves the coefficients ~1e-7 from glm (as in
        // r_validation_augment_penalized_glm.rs); the formulas themselves are exact.
        1e-6,
    );
}

#[test]
fn engine_negative_binomial_matches_glm_nb() {
    let opts = NegBinomialOptions {
        compute_inference: true,
        tolerance: ETOL,
        max_iterations: 200,
        ..Default::default()
    };
    let fit = fit_negbinomial(&Y_NB, &x_cols(), &opts).unwrap();
    let (l, r) = link_resp(|o| fit.predict_se(&new_cols(), o));
    // theta is estimated by an alternation that stops at MASS's tolerance.
    check_glm(
        "engine NB",
        &l,
        &r,
        [
            &NB_ETA, &NB_SE_ETA, &NB_MU, &NB_SE_MU, &NB_MU_LWR, &NB_MU_UPR,
        ],
        1e-4,
    );
}

// ------------------------------------------------------------ dedicated GLM regressors

#[test]
fn dedicated_glms_match_predict_glm() {
    // Poisson: fitted with the training offset; new rows have no offset, so the
    // link prediction is R's minus the new offset, with the same standard error.
    let p = PoissonRegressor::log()
        .compute_inference(true)
        .tolerance(ETOL)
        .max_iterations(200)
        .offset(col(&OFFSET))
        .build()
        .fit(&design(), &col(&Y_POIS))
        .unwrap();
    let l = p
        .predict_se(&new_design(), &PredictSeOptions::new().link())
        .unwrap();
    let eta: Vec<f64> = (0..5).map(|i| POIS_ETA[i] - NEW_OFFSET[i]).collect();
    cmp("dedicated Poisson eta", &l.fit, &eta, 1e-7);
    cmp("dedicated Poisson se_eta", &l.se_fit, &POIS_SE_ETA, 1e-7);

    let b = BinomialRegressor::logistic()
        .compute_inference(true)
        .tolerance(ETOL)
        .max_iterations(200)
        .build()
        .fit(&design(), &col(&Y_BIN))
        .unwrap();
    let (l, r) = link_resp(|o| b.predict_se(&new_design(), o));
    check_glm(
        "dedicated binomial",
        &l,
        &r,
        [
            &BIN_ETA,
            &BIN_SE_ETA,
            &BIN_MU,
            &BIN_SE_MU,
            &BIN_MU_LWR,
            &BIN_MU_UPR,
        ],
        1e-7,
    );

    let g = GammaRegressor::builder()
        .compute_inference(true)
        .tolerance(ETOL)
        .max_iterations(200)
        .build()
        .fit(&design(), &col(&Y_GAMMA))
        .unwrap();
    let (l, r) = link_resp(|o| g.predict_se(&new_design(), o));
    check_glm(
        "dedicated Gamma",
        &l,
        &r,
        [
            &GAMMA_ETA,
            &GAMMA_SE_ETA,
            &GAMMA_MU,
            &GAMMA_SE_MU,
            &GAMMA_MU_LWR,
            &GAMMA_MU_UPR,
        ],
        1e-7,
    );

    let nb = NegativeBinomialRegressor::builder()
        .compute_inference(true)
        .estimate_theta(true)
        .tolerance(ETOL)
        .max_iterations(200)
        .build()
        .fit(&design(), &col(&Y_NB))
        .unwrap();
    let (l, r) = link_resp(|o| nb.predict_se(&new_design(), o));
    check_glm(
        "dedicated NB",
        &l,
        &r,
        [
            &NB_ETA, &NB_SE_ETA, &NB_MU, &NB_SE_MU, &NB_MU_LWR, &NB_MU_UPR,
        ],
        1e-4,
    );
}

// ------------------------------------------------------------ heteroskedasticity

#[test]
fn breusch_pagan_and_white_match_lmtest() {
    let f = OlsRegressor::builder()
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    let e = &f.result().residuals;
    for (label, got, want) in [
        (
            "bptest",
            breusch_pagan(e, &design(), true).unwrap(),
            BP_KOENKER,
        ),
        (
            "bptest(studentize = FALSE)",
            breusch_pagan(e, &design(), false).unwrap(),
            BP_CLASSIC,
        ),
        ("White", white_test(e, &design()).unwrap(), WHITE),
    ] {
        let d = [
            (got.statistic - want[0]).abs(),
            (got.df - want[1]).abs(),
            (got.p_value - want[2]).abs(),
        ];
        println!(
            "{label}: max abs diff {:.3e}",
            d.iter().cloned().fold(0.0, f64::max)
        );
        assert!(d[0] < 1e-9 * want[0].max(1.0), "{label} statistic {got:?}");
        assert_eq!(got.df, want[1], "{label} df");
        assert!(d[2] < 1e-10, "{label} p-value {got:?}");
    }
}

// ------------------------------------------------------------ partial residuals

#[test]
fn partial_residuals_match_r() {
    let ols = OlsRegressor::builder()
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    let p = partial_residuals(&ols, &design(), &col(&Y_LIN)).unwrap();
    cmp(
        "partial OLS x1",
        &p[0].partial_residual,
        &PARTIAL_OLS_X1,
        1e-9,
    );
    cmp(
        "partial OLS x2",
        &p[1].partial_residual,
        &PARTIAL_OLS_X2,
        1e-9,
    );

    let wls = WlsRegressor::builder()
        .weights(col(&W))
        .build()
        .fit(&design(), &col(&Y_LIN))
        .unwrap();
    let p = partial_residuals(&wls, &design(), &col(&Y_LIN)).unwrap();
    cmp(
        "partial WLS x1",
        &p[0].partial_residual,
        &PARTIAL_WLS_X1,
        1e-9,
    );
    cmp(
        "partial WLS x2",
        &p[1].partial_residual,
        &PARTIAL_WLS_X2,
        1e-9,
    );

    let mut x = x_cols();
    x.push(OFFSET.to_vec());
    let opts = PoissonOptions {
        offset_column: Some(3),
        tolerance: ETOL,
        max_iterations: 200,
        ..Default::default()
    };
    let fit = fit_poisson(&Y_POIS, &x, &opts).unwrap();
    let p = partial_residuals_glm(&fit, &Y_POIS, &x).unwrap();
    cmp(
        "partial Poisson x1",
        &p[0].partial_residual,
        &PARTIAL_POIS_X1,
        1e-8,
    );
    cmp(
        "partial Poisson x2",
        &p[1].partial_residual,
        &PARTIAL_POIS_X2,
        1e-8,
    );
}

#[test]
fn added_variable_matches_car_formula() {
    let av = added_variable(&design(), &col(&Y_LIN), None, true).unwrap();
    cmp("AV OLS x1 x", &av[0].x_residual, &AV_OLS_X1_X, 1e-9);
    cmp("AV OLS x1 y", &av[0].y_residual, &AV_OLS_X1_Y, 1e-9);
    cmp("AV OLS x2 x", &av[1].x_residual, &AV_OLS_X2_X, 1e-9);
    cmp("AV OLS x2 y", &av[1].y_residual, &AV_OLS_X2_Y, 1e-9);
    assert!((av[0].slope - OLS_COEF[1]).abs() < 1e-9);
    assert!((av[1].slope - OLS_COEF[2]).abs() < 1e-9);

    let w = col(&W);
    let av = added_variable(&design(), &col(&Y_LIN), Some(&w), true).unwrap();
    cmp("AV WLS x1 x", &av[0].x_residual, &AV_WLS_X1_X, 1e-9);
    cmp("AV WLS x1 y", &av[0].y_residual, &AV_WLS_X1_Y, 1e-9);
    assert!((av[0].slope - WLS_COEF[1]).abs() < 1e-9);
}

// ------------------------------------------------------------ AFT survival

#[test]
fn aft_survival_curves_match_psurvreg() {
    let x = design();
    let t = col(&TIME);
    let event: Vec<bool> = EVENT.iter().map(|&e| e > 0.5).collect();
    for (dist, surv, quant) in [
        (AftDistribution::Weibull, &SURV_WEIBULL, &QUANT_WEIBULL),
        (
            AftDistribution::LogNormal,
            &SURV_LOGNORMAL,
            &QUANT_LOGNORMAL,
        ),
        (
            AftDistribution::LogLogistic,
            &SURV_LOGLOGISTIC,
            &QUANT_LOGLOGISTIC,
        ),
    ] {
        let f = AftRegressor::builder()
            .distribution(dist)
            .tolerance(1e-12)
            .max_iterations(500)
            .build()
            .fit(&x, &t, &event)
            .unwrap();
        let label = dist.as_str();
        let s = f.survival_curve(&SURV_X0, &SURV_TIMES);
        cmp(&format!("{label} S(t|x)"), &col(&s), surv, 1e-6);
        let q = f.quantiles(&SURV_X0, &SURV_PROBS);
        // Newton stops ~1e-7 (relative) from survreg for the log-logistic fit.
        cmp(&format!("{label} quantiles"), &col(&q), quant, 1e-6);

        // The family-function result gives the same curve.
        let opts = AftOptions {
            dist,
            tolerance: 1e-12,
            max_iterations: 500,
            ..Default::default()
        };
        let r = fit_aft(&TIME, &x_cols(), &EVENT, &opts).unwrap();
        assert_eq!(r.distribution(), Some(dist));
        let s2 = r.survival_curve(&SURV_X0, &SURV_TIMES);
        cmp(&format!("{label} AftResult S(t|x)"), &col(&s2), surv, 1e-6);
        assert_eq!(r.survival_curve(&SURV_X0, &[0.0])[0], 1.0);
        assert!(r.survival_curve(&[0.4], &[1.0])[0].is_nan());
    }
}
